    implementing = authority.transition(
        identifier,
        "record_implementation_started",
        {
                "git": {
                    "schema_version": "strixnova.git-work-area.v1",
                    "repository": str(tmp_path.resolve()),
                    "work_item_id": identifier,
                    "target_ref": "main",
